PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS `colors` ( `id` integer NOT NULL PRIMARY KEY AUTOINCREMENT ,  `name` varchar(191) NOT NULL );
CREATE TABLE IF NOT EXISTS `directions` ( `start_place_id` varchar(191) NOT NULL ,  `end_place_id` varchar(191) NOT NULL ,  `directions_data` json NOT NULL ,  UNIQUE (`start_place_id`,`end_place_id`) );
CREATE TABLE IF NOT EXISTS "attractions" (
	`id` integer PRIMARY KEY AUTOINCREMENT,
	`old_id` numeric,
	`name` text NOT NULL,
	`name_local` text,
	`description` text,
	`address` text,
	`latitude` real,
	`longitude` real,
	`is_must_see` numeric,
	`is_predefined` numeric,
	`source_url` text,
	`city_id` integer NOT NULL,
	`very_old_id` integer,
	`country_code` text NOT NULL
);
CREATE TABLE IF NOT EXISTS "trips" (
	`id` integer PRIMARY KEY AUTOINCREMENT UNIQUE,
	`name` text NOT NULL,
	`start_date` numeric DEFAULT 'NULL',
	`end_date` numeric DEFAULT 'NULL',
	`old_id` text
);
CREATE TABLE IF NOT EXISTS itineraries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  trip_id INTEGER NOT NULL,
  "order" INTEGER NOT NULL,
  color_id INTEGER NOT NULL,
  old_id TEXT
);
CREATE TABLE IF NOT EXISTS itinerary_places (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  itinerary_id INTEGER NOT NULL,
  attraction_id INTEGER NOT NULL,
  "order" INTEGER NOT NULL,
  UNIQUE (itinerary_id, attraction_id)
);
CREATE TABLE IF NOT EXISTS trip_destinations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  trip_id INTEGER NOT NULL,
  country_code TEXT NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX "idx_directions_Direction_startPlaceId_idx" ON "directions" (`start_place_id`);
CREATE INDEX "idx_directions_Direction_endPlaceId_idx" ON "directions" (`end_place_id`);
COMMIT;
